<template><el-card><template #header>会员等级设置</template><el-table :data="rows" v-loading="loading"><el-table-column prop="name" label="等级"/><el-table-column prop="threshold" label="成长值"><template #default="s"><el-input-number v-model="s.row.threshold" :min="0"/></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button type="primary" link @click="save(s.row)">保存</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="暂无等级"/></el-card></template><script setup lang="ts">import {ref,onMounted} from 'vue';import {ElMessage} from 'element-plus';import {levelApi} from '@/api';const rows=ref<any[]>([]),loading=ref(false);async function load(){loading.value=true;try{const r:any=await levelApi.list();rows.value=r?.data||r||[]}catch(e:any){ElMessage.error(e?.message||'等级加载失败')}finally{loading.value=false}}async function save(r:any){if(Number(r.threshold)<0)return ElMessage.warning('成长值不能为负');try{await levelApi.update(r.id,{threshold:r.threshold});ElMessage.success('保存成功');load()}catch(e:any){ElMessage.error(e?.message||'保存失败')}}onMounted(load);</script>
